def can_transform(source, target):
    """Check if source can become target by rotating/flipping"""
    rotations = [source, 
                 [row[::-1] for row in source][::-1],
                 [row[::-1] for row in source],
                 list(zip(*source))[::-1]]
    for rot in rotations:
        # Check with value substitution
        n = len(rot)
        m = len(target)
        if n != m or len(rot[0]) != len(target[0]):
            continue
        # Map values
        mapping = {}
        valid = True
        for r in range(n):
            for c in range(len(rot[r])):
                s_val = rot[r][c]
                t_val = target[r][c]
                if s_val in mapping:
                    if mapping[s_val] != t_val:
                        valid = False
                        break
                else:
                    mapping[s_val] = t_val
        if valid:
            return True
    return False

