def is_horizontal_symmetric(grid):
    """Check if grid is symmetric left-right"""
    for r in range(len(grid)):
        for c in range(len(grid[0])//2):
            if grid[r][c] != grid[r][len(grid[0])-1-c]:
                return False
    return True

def is_vertical_symmetric(grid):
    """Check if grid is symmetric top-bottom"""
    h = len(grid)
    for r in range(h//2):
        for c in range(len(grid[0])):
            if grid[r][c] != grid[h-1-r][c]:
                return False
    return True

def has_any_symmetry(grid):
    return is_horizontal_symmetric(grid) or is_vertical_symmetric(grid)

